import{_ as t}from"./chunks/ai-pipeline-10-kpis-and-risks.DeHEvKpT.js";import{_ as r,o as i,c as a,a0 as o}from"./chunks/framework.DScjKhBS.js";const g=JSON.parse('{"title":"Failure modes and risk model","description":"The main ways quality and security degrade when PR review understanding is incomplete.","frontmatter":{"title":"Failure modes and risk model","description":"The main ways quality and security degrade when PR review understanding is incomplete."},"headers":[],"relativePath":"reports/pr-review-continuity/02-failure-modes-and-risk-model.md","filePath":"reports/pr-review-continuity/02-failure-modes-and-risk-model.md"}'),n={name:"reports/pr-review-continuity/02-failure-modes-and-risk-model.md"};function s(d,e,l,c,p,u){return i(),a("div",null,[...e[0]||(e[0]=[o('<figure class="report-section-image-wrapper" aria-labelledby="fig-pr-risk-model-caption"><img src="'+t+'" alt="A balance representing review pressure versus quality and risk outcomes" loading="lazy" class="report-section-image"><figcaption id="fig-pr-risk-model-caption">Risk model: review pressure must be balanced against quality and security outcomes</figcaption></figure><h1 id="failure-modes-and-risk-model" tabindex="-1">Failure modes and risk model <a class="header-anchor" href="#failure-modes-and-risk-model" aria-label="Permalink to &quot;Failure modes and risk model&quot;">​</a></h1><h2 id="primary-failure-modes" tabindex="-1">Primary failure modes <a class="header-anchor" href="#primary-failure-modes" aria-label="Permalink to &quot;Primary failure modes&quot;">​</a></h2><h3 id="_1-cognitive-overload-in-large-diffs" tabindex="-1">1) Cognitive overload in large diffs <a class="header-anchor" href="#_1-cognitive-overload-in-large-diffs" aria-label="Permalink to &quot;1) Cognitive overload in large diffs&quot;">​</a></h3><p>As change size and cross-file complexity increase, reviewers shift from reasoning to scanning. Defect detection quality falls before teams notice.</p><h3 id="_2-happy-path-approval" tabindex="-1">2) &quot;Happy-path approval&quot; <a class="header-anchor" href="#_2-happy-path-approval" aria-label="Permalink to &quot;2) &quot;Happy-path approval&quot;&quot;">​</a></h3><p>Review validates obvious behavior and tests the golden path, but fails to evaluate edge cases, rollback behavior, data integrity, and security boundaries.</p><h3 id="_3-ai-output-trust-drift" tabindex="-1">3) AI-output trust drift <a class="header-anchor" href="#_3-ai-output-trust-drift" aria-label="Permalink to &quot;3) AI-output trust drift&quot;">​</a></h3><p>AI-generated code that &quot;looks plausible&quot; is accepted without robust process-level verification. This is especially dangerous when reviewers are time-constrained.</p><h3 id="_4-knowledge-concentration" tabindex="-1">4) Knowledge concentration <a class="header-anchor" href="#_4-knowledge-concentration" aria-label="Permalink to &quot;4) Knowledge concentration&quot;">​</a></h3><p>Too much codebase understanding sits with one person. Their temporary absence turns routine review into high-risk review-by-proxy.</p><h3 id="_5-governance-bypass-under-pressure" tabindex="-1">5) Governance bypass under pressure <a class="header-anchor" href="#_5-governance-bypass-under-pressure" aria-label="Permalink to &quot;5) Governance bypass under pressure&quot;">​</a></h3><p>Teams skip risk labels, downgrade review rigor, or merge with weak rationale to hit delivery dates.</p><hr><h2 id="risk-taxonomy-for-constrained-review-periods" tabindex="-1">Risk taxonomy for constrained review periods <a class="header-anchor" href="#risk-taxonomy-for-constrained-review-periods" aria-label="Permalink to &quot;Risk taxonomy for constrained review periods&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Risk class</th><th>Typical trigger</th><th>Impact</th><th>Control type</th></tr></thead><tbody><tr><td><strong>Design drift</strong></td><td>Large scope PR with weak rationale</td><td>Long-term maintainability loss</td><td>PR intent contract + architecture checklist</td></tr><tr><td><strong>Logic regressions</strong></td><td>Limited reviewer bandwidth</td><td>Production defects, reverts</td><td>Deterministic tests + scenario checks</td></tr><tr><td><strong>Security miss</strong></td><td>Superficial review of auth/input/output paths</td><td>Vulnerabilities, client exposure</td><td>Security-focused review template + SAST gates</td></tr><tr><td><strong>Operational fragility</strong></td><td>No owner-level review of observability/deploy impact</td><td>Incident MTTR increase</td><td>Runtime readiness checklist</td></tr><tr><td><strong>Knowledge bottleneck</strong></td><td>Single reviewer dependency</td><td>Queue collapse, blocked delivery</td><td>Rotation + ownership expansion plan</td></tr></tbody></table><hr><h2 id="internal-alignment-with-existing-project-guidance" tabindex="-1">Internal alignment with existing project guidance <a class="header-anchor" href="#internal-alignment-with-existing-project-guidance" aria-label="Permalink to &quot;Internal alignment with existing project guidance&quot;">​</a></h2><p>This report extends existing project principles:</p><ul><li>Keep AI as <strong>first-pass assistant</strong>, not merge authority</li><li>Maintain <strong>human gate ownership</strong> for approval/merge</li><li>Complement diff review with <strong>outcome validation</strong> (scenarios/tests)</li><li>Use explicit governance controls for data, security, and auditability</li></ul><hr><h2 id="decision-rule" tabindex="-1">Decision rule <a class="header-anchor" href="#decision-rule" aria-label="Permalink to &quot;Decision rule&quot;">​</a></h2><p>When reviewer comprehension is uncertain, <strong>merge confidence must come from stronger evidence, not from speed pressure</strong>.</p><p>That means increasing objective checks and reducing unit-of-change size until confidence is restored.</p><hr><p><strong>Next:</strong> <a href="./reports/pr-review-continuity/03-operating-model-for-constrained-review-capacity.html">Operating model for constrained review capacity</a></p>',26)])])}const f=r(n,[["render",s]]);export{g as __pageData,f as default};
